package helpers

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

// DoubleCommand is the name of the calculator command the doubling concept
// runs: the CLI document declares `calc double VALUE`.
const DoubleCommand = "double"

// Doubled is what one run of the calculator's double command reported: the
// stdout the program printed and the integer read from it. Nothing here is
// calculated from the step's number; the integer is only what the program
// printed.
type Doubled struct {
	// Stdout is the program's stdout exactly as it was printed.
	Stdout string
	// Value is the integer the program printed on stdout.
	Value int
}

// RunDouble runs the kept calculator program's double command as a process
// from the host project root, passing value verbatim as the command's VALUE
// argument, and reports the integer the program printed on stdout. A non-zero
// exit, or stdout that is not an integer, is reported as an error.
func RunDouble(calculator *Calculator, value string) (*Doubled, error) {
	if calculator == nil || calculator.Path == "" {
		return nil, fmt.Errorf("run the calculator's %s command: no calculator is installed; the installation Given must run first", DoubleCommand)
	}
	run := exec.Command(calculator.Path, DoubleCommand, value)
	// The CLI document says the program is run from the host project root.
	run.Dir = calculator.Root
	// Inherit the ambient environment rather than creating a separate one.
	run.Env = os.Environ()
	var stdout, stderr bytes.Buffer
	run.Stdout = &stdout
	run.Stderr = &stderr
	if err := run.Run(); err != nil {
		if reported := strings.TrimSpace(stderr.String()); reported != "" {
			return nil, fmt.Errorf("run %s %s %s in %s: %w: %s", CalculatorName, DoubleCommand, value, calculator.Root, err, reported)
		}
		return nil, fmt.Errorf("run %s %s %s in %s: %w", CalculatorName, DoubleCommand, value, calculator.Root, err)
	}
	printed := stdout.String()
	number, err := strconv.Atoi(strings.TrimSpace(printed))
	if err != nil {
		return nil, fmt.Errorf("read the integer %s %s %s printed on stdout: %q is not an integer", CalculatorName, DoubleCommand, value, printed)
	}
	return &Doubled{Stdout: printed, Value: number}, nil
}

// Package helpers holds the code the calc suite's step definitions share.
package helpers

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
)

// CalculatorPackage is the Go package, relative to the host project root,
// that the declared calculator command is built from. The calculator CLI
// document states the program is built with go build from ./services/calc
// at the host root.
const CalculatorPackage = "./services/calc"

// CalculatorName is the file name given to the built calculator program.
const CalculatorName = "calc"

// BuildDir is the directory, relative to the host project root, the
// calculator program is built into: the host's tmp directory.
const BuildDir = "tmp"

// Calculator is an installed calculator program: the path of the program
// the Given built, and the host project root the CLI document says the
// program is run from.
type Calculator struct {
	// Path is the absolute path of the built calculator program.
	Path string
	// Root is the absolute path of the host project root.
	Root string
}

// HostRoot reports the host project root: the nearest directory at or above
// the working directory that holds a go.mod. The root is located from that
// module file alone, so a host project copied without its services still
// resolves to its own root instead of some directory outside the module.
func HostRoot() (string, error) {
	start, err := os.Getwd()
	if err != nil {
		return "", fmt.Errorf("locate the working directory: %w", err)
	}
	dir := start
	for {
		info, err := os.Stat(filepath.Join(dir, "go.mod"))
		if err == nil && !info.IsDir() {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("locate the host project root: no go.mod at or above %s", start)
		}
		dir = parent
	}
}

// BuildCalculator builds the declared calculator command as a program under
// the host project's tmp directory and reports where it was built, so a When
// can run it from the host project root.
func BuildCalculator() (*Calculator, error) {
	root, err := HostRoot()
	if err != nil {
		return nil, err
	}
	goTool, err := exec.LookPath("go")
	if err != nil {
		return nil, fmt.Errorf("find the go tool needed to build the calculator: %w", err)
	}
	outDir := filepath.Join(root, BuildDir)
	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return nil, fmt.Errorf("create the build directory %s: %w", outDir, err)
	}
	program := filepath.Join(outDir, CalculatorName+exeSuffix())

	build := exec.Command(goTool, "build", "-o", program, CalculatorPackage)
	build.Dir = root
	// Inherit the ambient build cache and temporary directory rather than
	// creating a separate one.
	build.Env = os.Environ()
	if output, err := build.CombinedOutput(); err != nil {
		if reported := strings.TrimSpace(string(output)); reported != "" {
			return nil, fmt.Errorf("build %s in %s: %w: %s", CalculatorPackage, root, err, reported)
		}
		return nil, fmt.Errorf("build %s in %s: %w", CalculatorPackage, root, err)
	}

	info, err := os.Stat(program)
	if err != nil {
		return nil, fmt.Errorf("the built calculator program is missing from %s: %w", program, err)
	}
	if info.IsDir() {
		return nil, fmt.Errorf("the built calculator program at %s is a directory", program)
	}
	return &Calculator{Path: program, Root: root}, nil
}

// exeSuffix is the extension an executable file carries on this platform.
func exeSuffix() string {
	if runtime.GOOS == "windows" {
		return ".exe"
	}
	return ""
}

package helpers

import (
	"fmt"
	"strconv"
	"strings"
)

// ExpectedNumber reads the whole number a step wrote — an optional minus sign
// followed by digits — as an integer. The value comes only from the step text;
// nothing is derived from the program's output here.
func ExpectedNumber(expected string) (int, error) {
	number, err := strconv.Atoi(strings.TrimSpace(expected))
	if err != nil {
		return 0, fmt.Errorf("read the expected whole number %q the step wrote: %w", expected, err)
	}
	return number, nil
}

// CheckDoubled compares the integer the kept run of the calculator's double
// command printed on stdout with the whole number the step expects. The
// observed number is only what the program printed, and the expected number is
// only what the step wrote: no doubling is performed here. A missing run, an
// unreadable expected number, or a difference between the two is reported as an
// error.
func CheckDoubled(doubled *Doubled, expected string) error {
	if doubled == nil {
		return fmt.Errorf("observe what %s %s printed on stdout: no run was kept; the doubling When must run first", CalculatorName, DoubleCommand)
	}
	want, err := ExpectedNumber(expected)
	if err != nil {
		return err
	}
	if doubled.Value != want {
		return fmt.Errorf("%s %s printed %d on stdout (%q), want %d", CalculatorName, DoubleCommand, doubled.Value, doubled.Stdout, want)
	}
	return nil
}

package steps

import "fixture/stepsrun/tests/calc/helpers"

//truebdd:concept given "installation"
func concept08bdc8ba20fbc17f8cbea598ca6da5bdbc121817e637f18277eb83c75896fcf3(state *State, args []string) error {
	// Build the declared calculator command as a program under the host's
	// tmp directory and keep its path for the When. The step carries no
	// value, so there is nothing in args to read.
	calculator, err := helpers.BuildCalculator()
	if err != nil {
		return err
	}
	state.Calculator = calculator
	return nil
}

package steps

import (
	"fmt"

	"fixture/stepsrun/tests/calc/helpers"
)

//truebdd:concept when "doubling"
func concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b(state *State, args []string) error {
	if len(args) != 1 {
		return fmt.Errorf("the doubling step expects the whole number as its one value, got %d", len(args))
	}
	// args[0] is the whole number the step wrote, optionally signed. It is
	// handed to the calculator's double command verbatim as its VALUE
	// argument; the step performs no arithmetic of its own.
	value := args[0]
	doubled, err := helpers.RunDouble(state.Calculator, value)
	if err != nil {
		return err
	}
	// Keep the integer the program printed on stdout for a Then to observe.
	state.Doubled = doubled
	return nil
}

package steps

import (
	"fmt"

	"fixture/stepsrun/tests/calc/helpers"
)

//truebdd:concept then "result"
func concepted1de9371d2a7b37ce77d82464ab6737cf25f6c86f592518873001398dd1313e(state *State, args []string) error {
	if len(args) != 1 {
		return fmt.Errorf("the result step expects the expected whole number as its one value, got %d", len(args))
	}
	// args[0] is the expected whole number as the step wrote it, optionally
	// signed. The observed number is only the integer the kept run of the
	// calculator's double command printed on stdout, so this step compares
	// and never doubles anything itself.
	return helpers.CheckDoubled(state.Doubled, args[0])
}

package steps

func Register(suite interface {
	Step(string, func(*State, []string) error)
}) {
	suite.Step("^the calculator is installed$", concept08bdc8ba20fbc17f8cbea598ca6da5bdbc121817e637f18277eb83c75896fcf3)

	suite.Step("^the Owner doubles (-?\\d+)$", concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b)

	suite.Step("^the result is (-?\\d+)$", concepted1de9371d2a7b37ce77d82464ab6737cf25f6c86f592518873001398dd1313e)
}

package steps

import "fixture/stepsrun/tests/calc/helpers"

// State is what the calc suite's steps share within one scenario.
type State struct {
	// Calculator is the calculator program the installation Given built,
	// kept so the When can run it.
	Calculator *helpers.Calculator
	// Doubled is what the doubling When's run of the calculator printed,
	// kept so a Then can observe the integer the program reported. It is
	// nil until that When has run.
	Doubled *helpers.Doubled
}
